/* IaC Genius CE — Dashboard tab for the Hermes dashboard.
 * The page is generated by the desk (`iacg_desk board`) and served by this plugin's backend at
 * /api/plugins/iacg-board/page. "Refresh" asks the desk to re-render the snapshot from its durable
 * store; the iframe then reloads. No build step: plain React elements from the dashboard SDK. */
(function () {
  "use strict";
  var SDK = window.__HERMES_PLUGIN_SDK__;
  var React = SDK.React;
  var h = React.createElement;
  var useState = SDK.hooks.useState, useEffect = SDK.hooks.useEffect, useRef = SDK.hooks.useRef;
  var API = "/api/plugins/iacg-board";

  function get(path) { return SDK.fetchJSON(API + path); }
  function post(path) { return SDK.fetchJSON(API + path, { method: "POST" }); }
  function errText(e) {
    var m = (e && (e.detail || e.message)) || String(e);
    return m.replace(/^Error:\s*/, "");
  }

  function BoardPage() {
    var s = useState(null), status = s[0], setStatus = s[1];
    var p = useState(null), pageHtml = p[0], setPageHtml = p[1];
    var e = useState(""), err = e[0], setErr = e[1];
    var b = useState(false), busy = b[0], setBusy = b[1];
    var v = useState(0), version = v[0], setVersion = v[1];
    var last = useRef(null);
    var pageRef = useRef(null);

    // Fit the pane to the viewport: the dashboard route wrapper is auto-height, so size from the
    // pane's actual top edge down to the bottom and re-fit on resize.
    useEffect(function () {
      function fit() {
        var el = pageRef.current;
        if (!el) return;
        var top = el.getBoundingClientRect().top;
        el.style.height = Math.max(360, window.innerHeight - top - 14) + "px";
      }
      fit();
      var t = setTimeout(fit, 60);
      window.addEventListener("resize", fit);
      return function () { clearTimeout(t); window.removeEventListener("resize", fit); };
    }, []);

    // Fetch through the host SDK (profile + auth), then render the desk's unchanged HTML document.
    useEffect(function () {
      var active = true;
      setPageHtml(null);
      SDK.authedFetch(API + "/page?v=" + version)
        .then(function (response) {
          if (!response.ok) throw new Error("Cannot load board (HTTP " + response.status + ")");
          return response.text();
        })
        .then(function (text) { if (active) setPageHtml(text); })
        .catch(function (error) { if (active) setErr(errText(error)); });
      return function () { active = false; };
    }, [version]);

    // Poll the snapshot time; swap the page when the desk writes a new one.
    useEffect(function () {
      var id = setInterval(function () {
        get("/status").then(function (x) {
          if (last.current && x.generated_at && x.generated_at !== last.current.generated_at) {
            setVersion(function (n) { return n + 1; });
          }
          last.current = x;
          setStatus(x);
        }).catch(function () { /* keep the last good board */ });
      }, 60000);
      return function () { clearInterval(id); };
    }, []);

    function refresh() {
      setBusy(true); setErr("");
      post("/refresh")
        .then(function (x) { last.current = x; setStatus(x); setVersion(version + 1); setBusy(false); })
        .catch(function (x) { setErr(errText(x)); setBusy(false); });
    }

    var when = status && status.generated_at
      ? "snapshot " + String(status.generated_at).replace("T", " ").slice(0, 16) + " UTC"
      : (status ? status.summary : "loading…");

    return h("div", { className: "iacg-page", ref: pageRef },
      h("div", { className: "iacg-bar" },
        h("div", { className: "iacg-title" },
          h("strong", null, "IaC Genius mission board"),
          h("span", { className: "iacg-age" }, " · " + when)),
        h("button", { className: "iacg-btn", type: "button", onClick: refresh, disabled: busy,
                      title: "Ask the desk to re-render the board from its durable store" },
          busy ? "Refreshing…" : "Refresh")),
      err ? h("div", { className: "iacg-err", role: "alert" }, err) : null,
      h("iframe", { className: "iacg-frame", title: "IaC Genius mission board",
                    srcDoc: pageHtml || undefined }));
  }

  window.__HERMES_PLUGINS__.register("iacg-board", BoardPage);
})();